    "content": "Doygun ve doygun olmayan zemin kavramları, emme (suction) tanımı ve ölçümü, zemin–su karakteristik eğrileri, efektif gerilme ilkesi, histerezis, kritik durum teorisi, zeminlerin dayanım ve deformasyon özellikleri, laboratuvar deneyleri (triaxial, permeabilite), modelleme ve mühendislik uygulamaları.",
