    "purpose": "Dersin amacı: yeraltı suyu beslenimi, depolanması, hareketinin kavranması ve mühendislik uygulamalarının yapılabilmesi sağlamaktır.",
    "content": "Yeraltı suyu ortamları, hidrolojik çevrim, yeraltı suyu hareketi ve Darcy Kanunu, kuyu hidroliği, akifer testi, yeraltı suyu modellemesi.",
    "methods": "Yüz yüze anlatım, problem çözme, soru-cevap.",
