      "Yeraltısuyu Modellemesine Giriş ve Model Türleri",
      "Sayısal Modelleme Yöntemleri (Sonlu Farklar)",
      "Bilgisayar Yazılımları ile Uygulama",
      "Yeraltı suyu hidrolojisi: kapsam ve temel kavramlar"
