    "purpose": "Dersin amacı; baraj türlerini, elemanlarını ve rezervuar tasarım ilkelerini (aktif/ölü hacim, taşkın kontrolü) öğretmek; dolgu ve beton ağırlık barajların tasarımını ve stabilite analizlerini (sızma, şev stabilitesi, devrilme/kayma) yapabilme becerisi kazandırmaktır. Ayrıca dolusavaklar, derivasyon tesisleri ve hidroelektrik enerji üretim tesislerinin yapısal bileşenlerinin projelendirilmesi konusunda yetkinlik sağlamaktır.",
    "content": "Baraj mühendisliğine giriş ve sınıflandırma, baraj elemanları, rezervuar tasarımı: aktif, ölü ve taşkın kontrol hacimleri, dolgu barajlar: malzeme, sızma ve şev stabilitesi analizleri, beton ağırlık barajlar: gövde tasarımı ve emniyet tahkikleri, kemer barajlar, dolusavak tasarımı, derivasyon tesisleri (batardolar ve tüneller), hidroelektrik enerji üretimi ve su kuvveti tesisleri bileşenleri.",
    "methods": "Yüz yüze anlatım, Proje Tasarımı, Problem Çözme.",
