    "purpose": "Bu dersin amacı, karmaşık zemin koşullarında yapı temellerinin tasarımı, analizi ve performans değerlendirmesi konularında ileri düzey bilgi kazandırmaktır. Öğrencilerin, farklı temel türlerinin davranışını anlayarak, uygun temel sistemlerini seçebilme ve mühendislik projelerinde güvenli, ekonomik çözümler geliştirme becerisi kazanmaları hedeflenmektedir.",
    "content": "Zemin–temel etkileşimi, derin ve yüzeysel temellerin analizi, oturma ve taşıma gücü hesapları, grup kazık davranışı, kazıklı radye temeller, kazık–zemin–yapı etkileşimi, derin kazılar, iksa sistemleri, temel mühendisliğinde zemin iyileştirme uygulamaları ve yeni nesil tasarım yöntemleri.",
