    "content": "Yapı zemin etkileşimi; zeminlerin gerilme-şekil değiştirme davranışı, zemin parametrelerinin belirlenmesi, taşıma gücü ve oturma, şev ve kazı stabilitesi, zemin-yapı etkileşimi, geoteknik modelleme, tasarım güvenliği, arazi ve laboratuvar verilerinin yorumu boyutlarıyla ele alınır.",
