    "purpose": "Sezgisel (Heuristik) ve Metasezgisel (Metaheuristik) Yöntemlerinin tanıtımı. Genetik Algoritmalar, Tavlanmış Benzetim (Simulated Annealing), Parçacık Sürü Optimizasyonu (PSO), Karınca Kolonisi Optimizasyonu gibi yöntemlerin teorisi ve çalışma prensiplerinin uygulamalı olarak anlatılması",
    "content": "Meta-Sezgisel Yöntemler: Geleneksel yöntemlerin başarısız olduğu NP-Zor ve karmaşık problemler için Genetik Algoritmalar ve Simulated Annealing (Tavlanmış Benzetim) gibi sezgisel yaklaşımlar incelenir. Uygulamalar: Öğrenilen tekniklerin özellikle Derin Öğrenme Optimizasyonu ve karmaşık Ağ Akış problemleri gibi gerçek dünya senaryolarına nasıl uygulandığı gösterilir.",
    "methods": "Temel teorinin hazır bir yazılım olan \"MATLAB\" ile ispatlanması ve uygulanması",
